<script setup lang="ts">
import { computed, shallowRef, watch } from 'vue'
import type { CharacterNode, CharacterEdge } from '../types/characterGraph'
import { characterMetrics, shortestCharacterPath, type CharacterPath } from '../utils/characterAnalysis'
const props = defineProps<{ nodes: CharacterNode[]; edges: CharacterEdge[]; selectedId: string | null; truncated: boolean }>()
const emit = defineEmits<{ selectNode: [id: string]; selectEdge: [id: string]; pathChange: [path: CharacterPath | null] }>()
const from = shallowRef(''), to = shallowRef(''), directed = shallowRef(true)
const metrics = computed(() => characterMetrics(props.nodes, props.edges))
const ranking = computed(() => metrics.value.ranking.filter(r => r.degree > 0).slice(0, 5))
const choices = computed(() => [...props.nodes].sort((a, b) => a.label.localeCompare(b.label, 'zh-CN')))
const path = computed(() => shortestCharacterPath(props.nodes, props.edges, from.value, to.value, directed.value))
const steps = computed(() => path.value?.edgeIds.map((id, i) => {
  const edge = props.edges.find(e => e.id === id)!, source = path.value!.nodeIds[i]!, target = path.value!.nodeIds[i + 1]!
  return { edge, source: props.nodes.find(n => n.id === source)!, target: props.nodes.find(n => n.id === target)!, text: edge.label, forward: !edge.directed || edge.source === source }
}) || [])
watch(path, value => emit('pathChange', value), { immediate: true })
function clear() { from.value = ''; to.value = '' }
</script>
<template>
  <details class="network-insights"><summary>关系分析 <small>当前可见 {{ nodes.length }} 个角色 · {{ metrics.components }} 组相连网络</small></summary><div class="insights-grid"><section><h3>直接关联较多的角色</h3><p class="analysis-note">每位邻居只计一次；多种关系不重复增加人数。</p><div class="ranked-characters"><button v-for="(row, index) in ranking" :key="row.node.id" @click="emit('selectNode', row.node.id)"><span>{{ index + 1 }}</span><strong>{{ row.node.label }}</strong><small>{{ row.degree }} 人</small></button><p v-if="!ranking.length" class="analysis-note">当前筛选下没有关联记录。</p></div></section><section><h3>查找两位角色的联系</h3><div class="path-controls"><label>起点<select v-model="from"><option value="">请选择角色</option><option v-for="node in choices" :key="node.id" :value="node.id">{{ node.label }}</option></select></label><label>终点<select v-model="to"><option value="">请选择角色</option><option v-for="node in choices" :key="node.id" :value="node.id">{{ node.label }}</option></select></label></div><div class="path-options"><label><input v-model="directed" type="checkbox">按关系箭头方向查找</label><button v-if="selectedId" @click="from = selectedId">选中角色作为起点</button><button v-if="from || to" @click="clear">清除路径</button></div><p v-if="from && to && !path" class="analysis-note" role="status">当前已加载且通过筛选的网络中，在6跳内没有找到符合方向的路径。可调整筛选或方向条件。</p><template v-else-if="path"><p class="path-result" role="status">{{ path.edgeIds.length === 0 ? '起点与终点相同' : `找到 ${path.edgeIds.length} 跳的最短联系，已在图中突出显示` }}</p><ol class="path-steps"><li v-for="step in steps" :key="step.edge.id"><button @click="emit('selectEdge', step.edge.id)">{{ step.source.label }} <span>{{ step.forward ? '→' : '←' }}</span> {{ step.target.label }}<small>{{ step.text }} · 查看出处</small></button></li></ol></template></section></div><p class="analysis-note scope-note">路径最多6跳。仅分析当前可见数据{{ truncated ? '（结果已截断）' : '' }}，受关系类别、剧透与其他筛选影响。路径表示关系相连，不代表两端存在可推断的剧情身份；分组按连通性划分。</p></details>
</template>
<style scoped>
.network-insights{border:1px solid #dce6d5;border-radius:12px;background:#fff;margin:18px 0;color:#536f5d}.network-insights>summary{padding:16px 20px;cursor:pointer;font-size:14px;min-height:48px}.network-insights>summary small{font-size:11px;color:#8c9c80;margin-left:16px}.insights-grid{display:grid;grid-template-columns:1fr 1.4fr;gap:30px;border-top:1px solid #e7ecdf;padding:20px}.insights-grid h3{font-size:15px;margin:0 0 12px;font-weight:550}.analysis-note{font-size:11px;line-height:1.9;color:#8a9c7e}.ranked-characters{display:grid;gap:6px}.ranked-characters button{display:flex;align-items:center;gap:10px;text-align:left;border:0;background:#f6f9f1;min-height:38px;font-size:12px}.ranked-characters strong{font-weight:500}.ranked-characters span{color:#a7b59c;font-size:10px}.ranked-characters small{margin-left:auto;color:#76906a}.path-controls{display:grid;grid-template-columns:1fr 1fr;gap:12px}.path-controls label{min-width:0;font-size:11px}.path-controls select{font-size:12px;min-width:0}.path-options{display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin-top:12px}.path-options label{display:flex;flex-direction:row;align-items:center;gap:6px;font-size:11px}.path-options input{width:14px;height:14px}.path-options button{font-size:10px;min-height:34px;padding:6px 8px}.path-result{font-size:12px;color:#5d8195}.path-steps{margin:12px 0;padding-left:18px}.path-steps button{text-align:left;background:#f0f5f7;border:0;font-size:12px;margin-bottom:6px}.path-steps small{display:block;margin-top:5px;font-size:10px;color:#829b9f}.path-steps span{color:#7599ae}.scope-note{padding:0 20px 16px;margin:0}@media(max-width:650px){.insights-grid{grid-template-columns:1fr;gap:22px;padding:16px}.network-insights>summary small{display:block;margin:8px 0 0 16px}}
</style>
